def W(ans, cand, k=3, f=None):
    f = f or (lambda v: M(v))
    out = []
    for c in cand:
        if c != ans and c not in out and c > 0: out.append(c)
    t = 1
    while len(out) < k:
        c = ans + t * (1 if t % 2 else -1); t += 1
        if c != ans and c not in out and c > 0: out.append(c)
    return [f(v) for v in out[:k]]
